export default function BotanikaLanguagePicker(props: Props) {
    const { style, color = "#F5F5F5", background = "#111112", font, icon = "globe", customIcon, iconSize = 16, iconColor, iconStroke = 1.5 } = props
    const locales = [{ id: "en", code: "en" }, { id: "vi", code: "vi" }]
    const initialLanguage = "en" as const
    const [language, setLanguage] = React.useState<"en" | "vi">(initialLanguage)
    React.useEffect(() => {
        const host = window as Window & { __botanikaInlineLanguage?: "en" | "vi" }
        if (!host.__botanikaInlineLanguage) host.__botanikaInlineLanguage = readInlineLanguage()
        const sync = () => setLanguage(host.__botanikaInlineLanguage ?? initialLanguage)
        sync()
        window.addEventListener("botanika:inline-language", sync)
        return () => window.removeEventListener("botanika:inline-language", sync)
    }, [])
    React.useEffect(() => mountPageTranslation(), [])
    const changeLanguage = setInlineLanguage
    const [open, setOpen] = React.useState(false)
    const [pending, setPending] = React.useState(false)
    const [error, setError] = React.useState(false)
    const root = React.useRef<HTMLDivElement>(null)
    const trigger = React.useRef<HTMLButtonElement>(null)
    const items = React.useRef<(HTMLButtonElement | null)[]>([])
    const menuId = React.useId()
    const options = locales.filter(locale => /^(en|vi)(-|$)/i.test(locale.code))
    const current = options.find(locale => /^vi/i.test(locale.code) === (language === "vi"))
    const vietnamese = /^vi/i.test(current?.code ?? "en")

    React.useEffect(() => {
        if (!open) return
        const first = options.findIndex(locale => locale.id === current?.id)
        items.current[Math.max(0, first)]?.focus()
        const outside = (event: PointerEvent) => {
            if (!root.current?.contains(event.target as Node)) setOpen(false)
        }
        window.addEventListener("pointerdown", outside)
        return () => window.removeEventListener("pointerdown", outside)
    }, [open])

    const close = () => {
        setOpen(false)
        trigger.current?.focus()
    }

    return (
        <div ref={root} style={{ ...style, position: "relative", overflow: "visible", color, fontFamily: "Instrument Sans, sans-serif", fontSize: 14, ...font }}
            onClick={event => event.stopPropagation()} onPointerDown={event => event.stopPropagation()}>
            <button ref={trigger} type="button" aria-label={vietnamese ? "Chọn ngôn ngữ" : "Choose language"}
                aria-haspopup="menu" aria-expanded={open} aria-controls={open ? menuId : undefined}
                disabled={pending || options.length < 2}
                onClick={() => { setError(false); setOpen(value => !value) }}
                onKeyDown={event => {
                    if (event.key === "ArrowDown" || event.key === "ArrowUp") { event.preventDefault(); setOpen(true) }
                }}
                style={{ width: "100%", height: "100%", display: "flex", alignItems: "center", justifyContent: "center", gap: 7, border: "1px solid rgba(255,255,255,.12)", borderRadius: 8, background, color, font: "inherit", cursor: pending ? "wait" : "pointer", opacity: pending ? .65 : 1 }}>
                {icon !== "none" && (icon === "custom" ? (
                    customIcon?.src && <img src={customIcon.src} width={iconSize} height={iconSize} alt="" aria-hidden="true" style={{ objectFit: "contain", flexShrink: 0 }} />
                ) : <svg width={iconSize} height={iconSize} viewBox="0 0 24 24" fill="none" stroke={iconColor || "currentColor"} strokeWidth={iconStroke} strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" style={{ flexShrink: 0 }}>
                    {icon === "globe" ? <><circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/></> : icon === "language" ? <><path d="M3 5h12M9 3v2M5 5c0 6 4 9 9 11M13 5c-1 6-5 10-10 12M14 21l4-10 4 10M15.5 17h5"/></> : <><path d="M3 3h11v11H3zM10 14v7h11V10h-7M5 7h7M8.5 5v2M6 7c1 3 3 4 5 5M11 7c-1 3-3 4-5 5M13 19l3-6 3 6M14 17h4"/></>}
                </svg>)}
                <span>{vietnamese ? "VI" : "EN"}</span>
                <svg width="10" height="10" viewBox="0 0 12 12" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true" style={{ transform: open ? "rotate(180deg)" : undefined }}><path d="m2 4 4 4 4-4"/></svg>
            </button>
            {open && <div id={menuId} role="menu" aria-label={vietnamese ? "Ngôn ngữ" : "Language"}
                onKeyDown={event => {
                    if (event.key === "Escape") { event.preventDefault(); event.stopPropagation(); close() }
                    if (["ArrowDown", "ArrowUp", "Home", "End"].includes(event.key)) {
                        event.preventDefault()
                        const index = items.current.findIndex(item => item === event.target)
                        const next = event.key === "Home" ? 0 : event.key === "End" ? options.length - 1 : (index + (event.key === "ArrowDown" ? 1 : -1) + options.length) % options.length
                        items.current[next]?.focus()
                    }
                    if (event.key === "Tab") setOpen(false)
                }}
                style={{ position: "absolute", top: "calc(100% + 8px)", right: 0, width: 176, padding: 6, boxSizing: "border-box", border: "1px solid #2B2B2E", borderRadius: 12, background: "#111112", boxShadow: "0 12px 36px #0008", zIndex: 100 }}>
                {options.map((locale, index) => {
                    const selected = locale.id === current?.id
                    return <button key={locale.id} ref={element => { items.current[index] = element }} type="button"
                        role="menuitemradio" aria-checked={selected} disabled={pending}
                        onClick={async () => {
                            if (selected) { close(); return }
                            setPending(true)
                            setError(false)
                            try { changeLanguage(/^vi/i.test(locale.code) ? "vi" : "en"); close() }
                            catch { setError(true) }
                            finally { setPending(false) }
                        }}
                        style={{ width: "100%", minHeight: 40, display: "flex", alignItems: "center", justifyContent: "space-between", padding: "10px 12px", border: 0, borderRadius: 7, color, background: selected ? "#27272A" : "transparent", font: "inherit", textAlign: "left", cursor: "pointer" }}>
                        <span lang={locale.code}>{/^vi/i.test(locale.code) ? "Tiếng Việt" : "English"}</span>
                        {selected && <span aria-hidden="true">✓</span>}
                    </button>
                })}
                {error && <div role="alert" style={{ padding: 10, color: "#FFB49D", fontSize: 12 }}>{vietnamese ? "Chưa đổi được ngôn ngữ, vui lòng thử lại" : "Couldn’t change language, please retry"}</div>}
            </div>}
        </div>
    )
}

addPropertyControls(BotanikaLanguagePicker, {
    color: { type: ControlType.Color, title: "Text", defaultValue: "#F5F5F5" },
    background: { type: ControlType.Color, title: "Background", defaultValue: "#111112" },
    font: { type: ControlType.Font, title: "Font", controls: "extended", defaultFontType: "sans-serif", defaultValue: { variant: "Regular", fontSize: "14px", lineHeight: "1.2em", letterSpacing: "0em" } },
    icon: { type: ControlType.Enum, title: "Icon", options: ["globe", "language", "translate", "custom", "none"], optionTitles: ["Globe", "Language", "Translate", "Custom Image", "None"], defaultValue: "globe" },
    customIcon: { type: ControlType.ResponsiveImage, title: "Icon Image", hidden: props => props.icon !== "custom" },
    iconSize: { type: ControlType.Number, title: "Icon Size", defaultValue: 16, min: 8, max: 32, step: 1, unit: "px", hidden: props => props.icon === "none" },
    iconColor: { type: ControlType.Color, title: "Icon Color", hidden: props => props.icon === "none" || props.icon === "custom" },
    iconStroke: { type: ControlType.Number, title: "Icon Stroke", defaultValue: 1.5, min: .5, max: 3, step: .25, hidden: props => props.icon === "none" || props.icon === "custom" },
})
